 a=np.deg2rad(lat);o=np.deg2rad(lon);return np.stack((np.cos(o)*np.cos(a),np.sin(o)*np.cos(a),np.sin(a)),axis=-1)
v=xyz(lat,lon);q=xyz(ty,tx)
for n in range(0,29):
 print('\\npoint',n,tx[n],ty[n])
 for j in [13,14,15]:
