   dots=np.einsum('ij,j->i',np.cross(vs,np.roll(vs,-1,axis=0)),q[n])
   # rank by minimum oriented / all arrangements
   if max(np.min(dots),np.min(-dots)) > -3e-7:
    print(j,i,dots,'score',max(np.min(dots),np.min(-dots)))
PY"

